6	 * character stripped. Both {@link NormalizeOwnerTelephone} (which additionally enforces the
7	 * 10-digit length) and {@link CheckOwnerTelephoneUnique} (which compares stored values) must
8	 * agree on this definition, so it lives here rather than being re-implemented at each site.
9	 */
10	final class OwnerTelephone {
11	
12	    private OwnerTelephone() {
13	    }
14	
15	    /** Strip every non-digit character; a {@code null} input normalises to an empty string. */
16	    static String normalize(String telephone) {
17	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
18	    }
19	}
